alter table public.aliyankeyye_transactions add column if not exists recipient_bank text not null default 'Aliyankee Sim Bank'; alter table public.aliyankeyye_transactions add column if not exists recipient_account text not null default ''; drop function if exists public.aliyankeyye_virtual_transfer(uuid,text,text,text,numeric,text); create or replace function public.aliyankeyye_virtual_transfer(p_sender uuid,p_email text,p_name text,p_bank text,p_account text,p_currency text,p_amount numeric,p_memo text) returns jsonb language plpgsql security definer set search_path=public as $$ declare sw public.aliyankeyye_wallets; rw public.aliyankeyye_wallets; recipient uuid; tx public.aliyankeyye_transactions; ref text; begin if p_amount<=0 or p_amount>100000000 then raise exception 'Invalid virtual transfer amount'; end if; if p_currency !~ '^[A-Z]{3}$' then raise exception 'Invalid currency'; end if; if p_bank not in ('Aliyankee Sim Bank','TM Virtual Bank','Aliyankee Sandbox Wallet') then raise exception 'Choose a supported virtual bank'; end if; if p_account !~ '^[0-9]{6,20}$' then raise exception 'Enter a virtual account number (6–20 digits)'; end if; select id into recipient from public.users where lower(coalesce(email,''))=lower(p_email) limit 1; insert into public.aliyankeyye_wallets(user_id,currency,balance) values(p_sender,p_currency,0) on conflict(user_id,currency) do nothing; select * into sw from public.aliyankeyye_wallets where user_id=p_sender and currency=p_currency for update; if sw.balance<p_amount then raise exception 'Insufficient virtual balance'; end if; update public.aliyankeyye_wallets set balance=balance-p_amount,updated_at=now() where id=sw.id returning * into sw; if recipient is not null and recipient<>p_sender then insert into public.aliyankeyye_wallets(user_id,currency,balance) values(recipient,p_currency,0) on conflict(user_id,currency) do nothing; select * into rw from public.aliyankeyye_wallets where user_id=recipient and currency=p_currency for update; update public.aliyankeyye_wallets set balance=balance+p_amount,updated_at=now() where id=rw.id; end if; ref:='AP-SIM-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12)); insert into public.aliyankeyye_transactions(reference,sender_user_id,recipient_user_id,recipient_email,recipient_name,recipient_bank,recipient_account,currency,amount,memo) values(ref,p_sender,case when recipient=p_sender then null else recipient end,lower(p_email),left(coalesce(p_name,''),80),p_bank,p_account,p_currency,p_amount,left(coalesce(p_memo,''),120)) returning * into tx; return jsonb_build_object('transaction',to_jsonb(tx),'balance',sw.balance,'recipient_user_id',recipient); end;$$; revoke all on function public.aliyankeyye_virtual_transfer(uuid,text,text,text,text,text,numeric,text) from public,anon,authenticated; grant execute on function public.aliyankeyye_virtual_transfer(uuid,text,text,text,text,text,numeric,text) to service_role;